def paint(n: int, ops: list[list[int]]) -> list[list[int]]:
    coords = sorted({x for op in ops for x in (op[1], op[2] + 1)})
    index = {x: i for i, x in enumerate(coords)}
    size = len(coords) - 1
    inf = 10**18

    minimum = [0] * (4 * size)
    second = [inf] * (4 * size)
    maximum = [0] * (4 * size)
    counts = {}

    def apply(node, value):
        old = minimum[node]
        if value <= old:
            return
        if value == inf:
            minimum[node] = maximum[node] = inf
            second[node] = inf
        else:
            minimum[node] = value
            if maximum[node] == old:
                maximum[node] = value

    def push(node):
        value = minimum[node]
        left = node * 2
        if minimum[left] < value:
            apply(left, value)
        if minimum[left + 1] < value:
            apply(left + 1, value)

    def pull(node):
        left = node * 2
        right = left + 1
        a, b = minimum[left], minimum[right]
        maximum[node] = max(maximum[left], maximum[right])
        if a == b:
            minimum[node] = a
            second[node] = min(second[left], second[right])
        elif a < b:
            minimum[node] = a
            second[node] = min(second[left], b)
        else:
            minimum[node] = b
            second[node] = min(a, second[right])

    def raise_range(node, lo, hi, start, end, colour):
        if end <= lo or hi <= start or minimum[node] >= colour:
            return
        if start <= lo and hi <= end and colour < second[node]:
            apply(node, colour)
            return
        push(node)
        mid = (lo + hi) // 2
        raise_range(node * 2, lo, mid, start, end, colour)
        raise_range(node * 2 + 1, mid, hi, start, end, colour)
        pull(node)

    def finish_range(node, lo, hi, start, end):
        if end <= lo or hi <= start or minimum[node] == inf:
            return
        if start <= lo and hi <= end and minimum[node] == maximum[node]:
            colour = minimum[node]
            if colour:
                counts[colour] = counts.get(colour, 0) + coords[hi] - coords[lo]
            apply(node, inf)
            return
        push(node)
        mid = (lo + hi) // 2
        finish_range(node * 2, lo, mid, start, end)
        finish_range(node * 2 + 1, mid, hi, start, end)
        pull(node)

    for op in reversed(ops):
        start, end = index[op[1]], index[op[2] + 1]
        if op[0] == 1:
            raise_range(1, 0, size, start, end, op[3])
        else:
            finish_range(1, 0, size, start, end)

    finish_range(1, 0, size, 0, size)
    return [[colour, counts[colour]] for colour in sorted(counts)]
